/**
 * Retrieve drug interactions for a specific gene symbol.
 * @param {string} geneSymbol - HGNC gene symbol (case-insensitive)
 * @returns {Array<{drug: string, approved: boolean, immunotherapy: boolean, antineoplastic: boolean, type: string, score: number}>}
 */
window.getGeneDrugInteractions = function(geneSymbol) {
    if (!geneSymbol || !window.DGIDB_DATA) return [];
    const key = String(geneSymbol).toUpperCase().trim();
    const raw = window.DGIDB_DATA[key];
    if (!raw) return [];
    return raw.map(item => ({
        drug: item[0],
        approved: item[1],
        immunotherapy: item[2],
        antineoplastic: item[3],
        type: item[4],
        score: item[5]
    }));
};

/**
 * Get all gene symbols in the dataset that have approved drug interactions.
 * @returns {string[]}
 */
window.getDruggableGenes = function() {
    if (!window.DGIDB_DATA) return [];
    return Object.keys(window.DGIDB_DATA).filter(g =>
        window.DGIDB_DATA[g].some(item => item[1] === true)
    );
};
